import csv, json, collections
from datetime import datetime, timezone
def ts(s): return datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
plan={}
for r in csv.DictReader(open('plan.csv')):
    if r['run_id'] in plan: assert plan[r['run_id']]==(r['suite'],r['curriculum'],r['retrieval'],r['decoder']), r
    plan[r['run_id']]=(r['suite'],r['curriculum'],r['retrieval'],r['decoder'])
launch={}
for r in csv.DictReader(open('launch_log.csv')):
    if r['run_id'] in launch: assert launch[r['run_id']]==(r['started_at'],r['worker']), r
    launch[r['run_id']]=(r['started_at'],r['worker'])
ev={}
for r in csv.DictReader(open('eval_results.csv')):
    if r['run_id'] in ev: assert ev[r['run_id']]==r['pass_rate']
    ev[r['run_id']]=r['pass_rate']
rt={}
for r in csv.DictReader(open('runtime.csv')):
    if r['run_id'] in rt: assert rt[r['run_id']]==r['finished_at']
    rt[r['run_id']]=r['finished_at']
ret={}
for r in csv.DictReader(open('retention_log.csv')):
    assert r['run_id'] not in ret
    ret[r['run_id']]=(r['dropped_at'],r['reason'])
rec={}
import glob
for f in sorted(glob.glob('recovered/*.csv')):
    for r in csv.DictReader(open(f)):
        v=r['pass_rate_pct']
        if r['run_id'] in rec: assert abs(float(rec[r['run_id']])-float(v))<1e-9,(r,rec[r['run_id']])
        rec[r['run_id']]=v
suites=json.load(open('suites.json'))
pol=json.load(open('retention_policy.json'))
digest={r['date']:(int(r['n_runs']),r['sum_pass_rate']) for r in csv.DictReader(open('daily_digest.csv'))}
rlog=list(csv.DictReader(open('recovery_log.csv')))
def floor_at(t):
    for v in pol['versions']:
        if ts(v['from'])<=t<ts(v['to']): return v['floor']
    return None
